import{_ as t,o as a,c as n,b6 as i}from"./chunks/framework.BUXTSoD9.js";const p=JSON.parse('{"title":"Designing Pages and Buttons with UI Design Guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"en/stage-2/frontend/multi-product-ui/index.md","filePath":"en/stage-2/frontend/multi-product-ui/index.md"}'),s={name:"en/stage-2/frontend/multi-product-ui/index.md"};function o(l,e,r,h,u,d){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="designing-pages-and-buttons-with-ui-design-guidelines" tabindex="-1">Designing Pages and Buttons with UI Design Guidelines <a class="header-anchor" href="#designing-pages-and-buttons-with-ui-design-guidelines" aria-label="Permalink to “Designing Pages and Buttons with UI Design Guidelines”">​</a></h1><p>Many people say &quot;I want the page to look more like Apple&quot; or &quot;I want the buttons to feel more premium,&quot; but when they actually start working, they often get stuck on one question:</p><p><strong>What exactly should I reference?</strong></p><p>Staring at screenshots and copying them only teaches you whether something &quot;looks similar.&quot; But when you open the design guidelines from Apple, Google, Microsoft, and Atlassian, you realize that what makes them impressive is not their visual style -- it&#39;s that <strong>they clearly articulate design problems</strong>: what to highlight first on a page, how to rank buttons, how to emphasize actions. These judgment criteria are the real core.</p><blockquote><p>Referencing design guidelines is not about making something &quot;look like someone else&#39;s work&quot; -- it&#39;s about learning how others make design decisions.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Why learn this now</p><p>Design rules have already been trained into models, absorbed as defaults in design tools, and AI can even learn from a few screenshots. But it&#39;s still worth understanding where these rules come from and why they were defined this way.</p></div><h2 id="first-read-a-few-excerpts-and-feel-the-difference" tabindex="-1">First, read a few excerpts and feel the difference <a class="header-anchor" href="#first-read-a-few-excerpts-and-feel-the-difference" aria-label="Permalink to “First, read a few excerpts and feel the difference”">​</a></h2><p>If you used to think &quot;design guidelines are just about style,&quot; read a few lines from the official sources first.</p><p>In everyday team discussions, we often say things like:</p><ul><li>Make a dropdown</li><li>Put a menu here</li><li>Add a few features to the menu bar</li><li>Put two buttons here, one for confirm and one for cancel</li></ul><p>That sounds fine, but in major design guidelines, these terms are not vague concepts -- they are broken down in great detail.</p><table tabindex="0"><thead><tr><th style="text-align:left;">What we casually say</th><th style="text-align:left;">Official source</th><th style="text-align:left;">In short</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;Make a menu&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">&quot;A menu reveals its options...&quot;</a></td><td style="text-align:left;"><code>Menu</code> is for triggering actions</td></tr><tr><td style="text-align:left;">&quot;Put features in the menu bar&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">&quot;menu bar menus contain all the commands...&quot;</a></td><td style="text-align:left;">This is the app-level command menu at the top</td></tr><tr><td style="text-align:left;">&quot;Make a dropdown&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">&quot;A pop-up list lets the user choose one option among several.&quot;</a></td><td style="text-align:left;"><code>pop-up</code> is for picking one value from a list</td></tr><tr><td style="text-align:left;">&quot;Also make a dropdown&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">&quot;A pull-down list is generally used for selecting commands in a specific context.&quot;</a></td><td style="text-align:left;"><code>pull-down</code> is for triggering a context-specific command</td></tr><tr><td style="text-align:left;">&quot;Can&#39;t a menu also be used for filtering?&quot;</td><td style="text-align:left;">Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">&quot;If you need to collect information from people, try a select, dropdown, or combobox instead.&quot;</a></td><td style="text-align:left;"><code>Menu</code> is not for value selection</td></tr><tr><td style="text-align:left;">&quot;Can&#39;t a menu be used for navigation?&quot;</td><td style="text-align:left;">Material: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">&quot;Menus should not be used as a primary method for navigation within an app.&quot;</a></td><td style="text-align:left;"><code>Menu</code> is not for primary navigation</td></tr><tr><td style="text-align:left;">&quot;Just write OK / Cancel on the buttons&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">&quot;Always use &#39;Cancel&#39; to title a button that cancels the alert&#39;s action.&quot;</a></td><td style="text-align:left;">Button labels shouldn&#39;t be arbitrary</td></tr></tbody></table><blockquote><p>All the quotes in the table are clickable and will take you to the corresponding official page.</p></blockquote><p>This is what strikes people most when they read design guidelines for the first time:</p><blockquote><p>We often think we&#39;re discussing UI, but most of the time we&#39;re just communicating with a bunch of vague words.</p></blockquote><p>Apple won&#39;t just say &quot;make a menu&quot;; it goes on to distinguish:</p><ul><li><code>menu</code></li><li><code>menu bar menu</code></li><li><code>pop-up button</code></li><li><code>pull-down button</code></li><li><code>context menu</code></li></ul><p>Fluent won&#39;t just say &quot;dropdown&quot;; it goes on to distinguish:</p><ul><li><code>menu</code></li><li><code>dropdown</code></li><li><code>select</code></li><li><code>combobox</code></li></ul><p>This is why design guidelines are necessary.</p><p>They exist not to make pages look more professional, but so that when a team discusses UI, everyone isn&#39;t picturing something different.</p><h2 id="what-you-will-learn" tabindex="-1">What you will learn <a class="header-anchor" href="#what-you-will-learn" aria-label="Permalink to “What you will learn”">​</a></h2><ol><li>Why you should look at design guidelines before designing pages and buttons</li><li>Which parts of Apple, Material, Fluent, and Atlassian guidelines are most worth referencing</li><li>How to design clear &quot;page hierarchy&quot; and &quot;button hierarchy&quot;</li><li>How to get AI to reference established guidelines when generating pages and buttons</li></ol><h2 id="_1-why-design-guidelines-help-you-build-clearer-pages" tabindex="-1">1. Why design guidelines help you build clearer pages <a class="header-anchor" href="#_1-why-design-guidelines-help-you-build-clearer-pages" aria-label="Permalink to “1. Why design guidelines help you build clearer pages”">​</a></h2><p>After reading the excerpts above, you&#39;ll notice a key point:</p><p><strong>Design guidelines are not icing on the cake -- they start by getting the terminology right.</strong></p><p>Many pages don&#39;t look good not because the color palette isn&#39;t sophisticated enough, but because the information hierarchy is chaotic.</p><p>Many buttons aren&#39;t usable not because the border radius is wrong, but because:</p><ul><li>There are too many primary buttons, and users don&#39;t know which one to click</li><li>Destructive buttons look the same as normal buttons</li><li>Every button on the page is competing for attention</li><li>Button styles and semantics are inconsistent across different pages</li></ul><p>Mature design guidelines exist precisely to solve these problems. They typically define:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Guideline content</th><th style="text-align:left;">What problem it solves</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Page hierarchy</strong></td><td style="text-align:left;">Where to look first, where to look next, how to organize information</td></tr><tr><td style="text-align:left;"><strong>Visual foundations</strong></td><td style="text-align:left;">How to unify color, spacing, typography, border radius, shadows</td></tr><tr><td style="text-align:left;"><strong>Button hierarchy</strong></td><td style="text-align:left;">How to distinguish primary, secondary, text, and destructive buttons</td></tr><tr><td style="text-align:left;"><strong>State rules</strong></td><td style="text-align:left;">How to represent hover, focus, disabled, loading states</td></tr><tr><td style="text-align:left;"><strong>Interaction semantics</strong></td><td style="text-align:left;">Which button means &quot;confirm,&quot; which means &quot;cancel,&quot; which means &quot;more actions&quot;</td></tr></tbody></table><p>So what design guidelines really provide is not a &quot;skin&quot; but a set of <strong>judgment criteria</strong>.</p><h2 id="_2-when-referencing-major-design-guidelines-what-should-you-focus-on" tabindex="-1">2. When referencing major design guidelines, what should you focus on <a class="header-anchor" href="#_2-when-referencing-major-design-guidelines-what-should-you-focus-on" aria-label="Permalink to “2. When referencing major design guidelines, what should you focus on”">​</a></h2><h3 id="_2-1-reference-apple-learn-to-define-things-precisely-enough" tabindex="-1">2.1 Reference Apple: Learn to &quot;define things precisely enough&quot; <a class="header-anchor" href="#_2-1-reference-apple-learn-to-define-things-precisely-enough" aria-label="Permalink to “2.1 Reference Apple: Learn to &quot;define things precisely enough&quot;”">​</a></h3><p>What&#39;s most worth learning from Apple is not just its visual restraint, but how it defines concepts in fine detail.</p><p>For what many teams casually call &quot;menu&quot; or &quot;dropdown,&quot; Apple breaks it down further:</p><ul><li><code>menu</code>: A set of commands, options, or states</li><li><code>menu bar menu</code>: An app-level command collection</li><li><code>pop-up button</code>: Choose one value</li><li><code>pull-down button</code>: Trigger a command in the current context</li><li><code>context menu</code>: Common actions related to the current object or task</li></ul><p>This distinction is crucial because it directly affects:</p><ul><li>Whether the component is for selecting values or triggering actions</li><li>Whether it belongs to a local section of the page or to the app level</li><li>Whether it should persistently display the current selection or only temporarily expand commands</li></ul><p>When you start thinking at this level of granularity, the pages you design will suddenly become much clearer.</p><h3 id="_2-2-reference-apple-learn-page-hierarchy-and-restraint" tabindex="-1">2.2 Reference Apple: Learn page hierarchy and restraint <a class="header-anchor" href="#_2-2-reference-apple-learn-page-hierarchy-and-restraint" aria-label="Permalink to “2.2 Reference Apple: Learn page hierarchy and restraint”">​</a></h3><p>Apple&#39;s Human Interface Guidelines are particularly good for learning two things:</p><ul><li>How to establish clear hierarchy on a page</li><li>How to keep controls explicit without them stealing the spotlight</li></ul><p>Apple emphasizes <code>Hierarchy</code>, <code>Harmony</code>, and <code>Consistency</code>. This means when designing a page, you need to answer:</p><ul><li>What is the most important information on the current page</li><li>What is the user&#39;s primary task</li><li>Which action should be most prominent, and which should recede</li></ul><p>If you reference Apple for page design, focus on:</p><ul><li>Don&#39;t make the above-the-fold content too fragmented; focus on core content first</li><li>Use whitespace, font sizes, and grouping to create order, rather than stacking lots of borders</li><li>Don&#39;t make all buttons high-emphasis; only key actions should stand out the most</li></ul><h3 id="_2-3-reference-material-learn-clear-page-structure" tabindex="-1">2.3 Reference Material: Learn clear page structure <a class="header-anchor" href="#_2-3-reference-material-learn-clear-page-structure" aria-label="Permalink to “2.3 Reference Material: Learn clear page structure”">​</a></h3><p>Material Design is great for learning &quot;how pages organize task flows.&quot;</p><p>Many of its components and layout guidelines are designed to help you clarify:</p><ul><li>Whether a page is for browsing or for executing tasks</li><li>Whether the current page is meant for reading, selecting, or submitting</li><li>Which elements on a page should remain stable and which should respond to context changes</li></ul><p>If you reference Material for page design, focus on:</p><ul><li>Clear page sections with well-defined module responsibilities</li><li>Clear division between navigation, content areas, and action areas</li><li>Different button styles corresponding to different action priorities</li></ul><h3 id="_2-4-reference-fluent-learn-component-boundaries-and-button-hierarchy" tabindex="-1">2.4 Reference Fluent: Learn component boundaries and button hierarchy <a class="header-anchor" href="#_2-4-reference-fluent-learn-component-boundaries-and-button-hierarchy" aria-label="Permalink to “2.4 Reference Fluent: Learn component boundaries and button hierarchy”">​</a></h3><p>Fluent 2 is well-suited for admin panels, tool-type products, and complex form systems. What&#39;s most worth learning is that it directly tells you &quot;don&#39;t mix concepts.&quot;</p><p>For example, it explicitly states: if you want to &quot;collect information,&quot; don&#39;t keep using <code>menu</code>; instead, consider <code>select</code>, <code>dropdown</code>, or <code>combobox</code>.</p><p>This statement is important because it shatters the &quot;they&#39;re all basically the same&quot; assumption many people hold.</p><p>Fluent 2 also emphasizes:</p><ul><li>Action hierarchy</li><li>Component semantic boundaries</li><li>Clarity in dense information scenarios</li></ul><p>If you reference Fluent for button design, focus on:</p><ul><li><code>Primary button</code> for the most important action in the current context</li><li><code>Secondary button</code> for supporting actions</li><li><code>Subtle</code> and <code>Transparent</code> low-emphasis buttons for actions that shouldn&#39;t compete with the main flow</li><li>The more buttons on a page, the more you need to control visual priority</li></ul><h3 id="_2-5-reference-atlassian-learn-to-systematically-manage-pages-and-buttons" tabindex="-1">2.5 Reference Atlassian: Learn to systematically manage pages and buttons <a class="header-anchor" href="#_2-5-reference-atlassian-learn-to-systematically-manage-pages-and-buttons" aria-label="Permalink to “2.5 Reference Atlassian: Learn to systematically manage pages and buttons”">​</a></h3><p>The Atlassian Design System is especially suited for situations where &quot;one team builds many pages.&quot; It emphasizes:</p><ul><li>Foundations as the shared baseline</li><li>Tokens as a method for unifying visual decisions</li><li>Components as reusable interaction building blocks</li></ul><p>If you reference Atlassian for pages and buttons, the most valuable aspects are:</p><ul><li>Turning button size, color, border radius, and spacing into unified rules</li><li>Fixing the rhythm of page layouts</li><li>Making different pages consistent in structural language even when their content differs</li></ul><h2 id="_3-when-designing-pages-which-parts-of-the-guidelines-should-you-reference" tabindex="-1">3. When designing pages, which parts of the guidelines should you reference <a class="header-anchor" href="#_3-when-designing-pages-which-parts-of-the-guidelines-should-you-reference" aria-label="Permalink to “3. When designing pages, which parts of the guidelines should you reference”">​</a></h2><p>When you look at a design system, don&#39;t start by asking &quot;does this page look good?&quot; Instead, start by asking the following questions.</p><h3 id="_3-1-at-first-glance-is-the-page-hierarchy-clear" tabindex="-1">3.1 At first glance, is the page hierarchy clear <a class="header-anchor" href="#_3-1-at-first-glance-is-the-page-hierarchy-clear" aria-label="Permalink to “3.1 At first glance, is the page hierarchy clear”">​</a></h3><p>A page typically needs at least three layers:</p><ul><li><strong>Primary information</strong>: The most important content on the current page</li><li><strong>Supporting information</strong>: Content that helps explain or supplement</li><li><strong>Secondary actions</strong>: Actions that shouldn&#39;t interfere with the main task</li></ul><p>If the three layers aren&#39;t differentiated, the page becomes &quot;everything is important,&quot; which means &quot;nothing is important.&quot;</p><h3 id="_3-2-does-the-page-layout-serve-the-task-rather-than-just-stacking-modules" tabindex="-1">3.2 Does the page layout serve the task rather than just stacking modules <a class="header-anchor" href="#_3-2-does-the-page-layout-serve-the-task-rather-than-just-stacking-modules" aria-label="Permalink to “3.2 Does the page layout serve the task rather than just stacking modules”">​</a></h3><p>When referencing guidelines, pay special attention to:</p><ul><li>Whether the title area clearly states the page&#39;s purpose</li><li>Whether the main content area is organized around the task</li><li>Whether action buttons are placed near related content</li><li>Whether secondary information is appropriately de-emphasized</li></ul><h3 id="_3-3-do-the-page-actions-have-clear-priorities" tabindex="-1">3.3 Do the page actions have clear priorities <a class="header-anchor" href="#_3-3-do-the-page-actions-have-clear-priorities" aria-label="Permalink to “3.3 Do the page actions have clear priorities”">​</a></h3><p>Many pages show 6 buttons at a glance, and every one looks like a CTA -- this is a classic case of hierarchy breakdown.</p><p>A more reasonable approach is:</p><ul><li>One section typically has only one primary action</li><li>Secondary actions can use outlined, text, or lower-emphasis styles</li><li>Risky actions should not look the same as primary actions</li></ul><h2 id="_4-when-designing-buttons-which-parts-of-the-guidelines-should-you-reference" tabindex="-1">4. When designing buttons, which parts of the guidelines should you reference <a class="header-anchor" href="#_4-when-designing-buttons-which-parts-of-the-guidelines-should-you-reference" aria-label="Permalink to “4. When designing buttons, which parts of the guidelines should you reference”">​</a></h2><p>Buttons are the easiest part to &quot;just throw together,&quot; but they&#39;re also the part that most reveals whether a design system is mature.</p><h3 id="_4-1-classify-buttons-by-semantics-first-then-by-style" tabindex="-1">4.1 Classify buttons by &quot;semantics&quot; first, then by &quot;style&quot; <a class="header-anchor" href="#_4-1-classify-buttons-by-semantics-first-then-by-style" aria-label="Permalink to “4.1 Classify buttons by &quot;semantics&quot; first, then by &quot;style&quot;”">​</a></h3><p>Don&#39;t start by thinking &quot;blue button or black button.&quot; First think about what role this button plays.</p><p>Common button roles can be classified as:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button type</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Common style strategy</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary</strong></td><td style="text-align:left;">The most critical action in the current section</td><td style="text-align:left;">Filled, high contrast, most prominent</td></tr><tr><td style="text-align:left;"><strong>Secondary</strong></td><td style="text-align:left;">Supporting actions</td><td style="text-align:left;">Outlined or lower emphasis</td></tr><tr><td style="text-align:left;"><strong>Tertiary / Text</strong></td><td style="text-align:left;">Minor actions</td><td style="text-align:left;">Text-only or low visual weight</td></tr><tr><td style="text-align:left;"><strong>Destructive</strong></td><td style="text-align:left;">Risky actions like delete, disable, clear</td><td style="text-align:left;">Warning color or explicit risk styling</td></tr><tr><td style="text-align:left;"><strong>Icon button</strong></td><td style="text-align:left;">Local tool actions</td><td style="text-align:left;">Minimal, close to context</td></tr></tbody></table><h3 id="_4-2-don-t-put-too-many-primary-buttons-on-one-page" tabindex="-1">4.2 Don&#39;t put too many Primary Buttons on one page <a class="header-anchor" href="#_4-2-don-t-put-too-many-primary-buttons-on-one-page" aria-label="Permalink to “4.2 Don&#39;t put too many Primary Buttons on one page”">​</a></h3><p>This is the most common trap for beginners.</p><p>If a page has 4 primary buttons, then there are effectively no primary buttons. The whole point of a primary button is to &quot;tell the user what they should do right now.&quot;</p><p>You can borrow the common approach used across many design systems:</p><ul><li>One main section typically has only one primary button</li><li>Cancel, back, and close generally shouldn&#39;t compete at the same level as confirm</li><li>Additional actions go into secondary buttons or menus</li></ul><h3 id="_4-3-buttons-should-communicate-state-changes" tabindex="-1">4.3 Buttons should communicate state changes <a class="header-anchor" href="#_4-3-buttons-should-communicate-state-changes" aria-label="Permalink to “4.3 Buttons should communicate state changes”">​</a></h3><p>Design guidelines typically spell out button states clearly:</p><ul><li>Default state</li><li>Hover state</li><li>Focus state</li><li>Disabled state</li><li>Loading state</li><li>Destructive state</li></ul><p>This matters because a button is not a static image -- it&#39;s one of the most frequently triggered controls during user interaction.</p><h3 id="_4-4-button-copy-is-also-part-of-the-design" tabindex="-1">4.4 Button copy is also part of the design <a class="header-anchor" href="#_4-4-button-copy-is-also-part-of-the-design" aria-label="Permalink to “4.4 Button copy is also part of the design”">​</a></h3><p>Button labels aren&#39;t just a &quot;copywriting issue&quot; -- they directly affect user comprehension.</p><p>For example:</p><ul><li><code>Save</code></li><li><code>Save Changes</code></li><li><code>Publish Now</code></li><li><code>Delete Project</code></li><li><code>Move to Trash</code></li></ul><p>These labels convey completely different psychological expectations. Mature guidelines typically require button labels to clearly express the action rather than using vague wording.</p><h2 id="_5-a-practical-page-and-button-design-checklist" tabindex="-1">5. A practical page and button design checklist <a class="header-anchor" href="#_5-a-practical-page-and-button-design-checklist" aria-label="Permalink to “5. A practical page and button design checklist”">​</a></h2><p>When designing pages yourself, you can quickly run through this checklist first:</p><h3 id="page-checklist" tabindex="-1">Page checklist <a class="header-anchor" href="#page-checklist" aria-label="Permalink to “Page checklist”">​</a></h3><ul><li>Does the page title clearly state the current task</li><li>Is the most important above-the-fold information visible at a glance</li><li>Is the page organized by task flow rather than by whatever came to mind</li><li>Is there only one primary action in any given section</li><li>Is secondary content appropriately de-emphasized</li></ul><h3 id="button-checklist" tabindex="-1">Button checklist <a class="header-anchor" href="#button-checklist" aria-label="Permalink to “Button checklist”">​</a></h3><ul><li>Is this button a primary or secondary action</li><li>Why does it deserve to be more prominent than other buttons</li><li>Are there too many primary buttons on the page</li><li>Are destructive actions clearly marked</li><li>Is the button label specific enough</li></ul><h2 id="_6-how-to-use-ai-to-reference-established-guidelines-for-page-design" tabindex="-1">6. How to use AI to reference established guidelines for page design <a class="header-anchor" href="#_6-how-to-use-ai-to-reference-established-guidelines-for-page-design" aria-label="Permalink to “6. How to use AI to reference established guidelines for page design”">​</a></h2><p>This section is the most practical.</p><p>When many people ask AI to design a page, they only say:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Make me a settings page, make it look premium, reference Apple&#39;s style</span></span></code></pre></div><p>This kind of prompt is too vague, and AI usually ends up just imitating &quot;white background, rounded corners, shadows.&quot;</p><p>For beginners, a more practical approach is not to summarize everything yourself, but to directly paste <strong>key sentences from the official guidelines</strong> to AI.</p><p>This has two benefits:</p><ul><li>You don&#39;t need to &quot;translate&quot; the design philosophy yourself first</li><li>AI can more easily understand pages and buttons based on official definitions</li></ul><h3 id="_6-1-example-1-have-ai-reference-apple-to-design-a-settings-page" tabindex="-1">6.1 Example 1: Have AI reference Apple to design a settings page <a class="header-anchor" href="#_6-1-example-1-have-ai-reference-apple-to-design-a-settings-page" aria-label="Permalink to “6.1 Example 1: Have AI reference Apple to design a settings page”">​</a></h3><p>First, find a sentence from Apple&#39;s official text:</p><blockquote><p><a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p></blockquote><p>You can paste it directly to AI like this:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Reference this sentence from the Apple Human Interface Guidelines:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Help me design an account security settings page.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The page hierarchy should be clear, important information first, and groupings should be tidy.</span></span></code></pre></div><p>The key here is: you don&#39;t need to explain too much yourself; just paste Apple&#39;s original words directly.</p><h3 id="_6-2-example-2-have-ai-reference-fluent-to-design-admin-panel-buttons" tabindex="-1">6.2 Example 2: Have AI reference Fluent to design admin panel buttons <a class="header-anchor" href="#_6-2-example-2-have-ai-reference-fluent-to-design-admin-panel-buttons" aria-label="Permalink to “6.2 Example 2: Have AI reference Fluent to design admin panel buttons”">​</a></h3><p>First, find a sentence from Fluent&#39;s official text:</p><blockquote><p><a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>You can paste it directly to AI like this:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Reference this sentence from Fluent 2:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Help me design the buttons for a team management admin panel.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The &quot;Add Member&quot; button should be most prominent; Export, Filter, and More Actions should be lower emphasis; the Delete button should stand out separately.</span></span></code></pre></div><p>This sentence is especially great for beginners because it directly tells AI: don&#39;t put too many primary buttons in one area.</p><h3 id="_6-3-example-3-have-ai-reference-both-page-and-button-guidelines-simultaneously" tabindex="-1">6.3 Example 3: Have AI reference both page and button guidelines simultaneously <a class="header-anchor" href="#_6-3-example-3-have-ai-reference-both-page-and-button-guidelines-simultaneously" aria-label="Permalink to “6.3 Example 3: Have AI reference both page and button guidelines simultaneously”">​</a></h3><p>You can also paste two original sentences at once and have AI reference both the page and button guidelines:</p><blockquote><p>Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p><p>Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>Then write it like this:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Reference the following two design guideline excerpts:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Apple: &quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fluent: &quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Help me design a project detail page.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The page includes project introduction, members, recent activity, and settings entry.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The page hierarchy should be clear, keep only one primary button, and make other buttons less prominent.</span></span></code></pre></div><p>This approach is especially suitable for beginners because all you need to do is copy the original text and add a couple of sentences about your own requirements.</p><h2 id="_7-how-to-use-ai-to-reference-button-guidelines-and-directly-generate-button-designs" tabindex="-1">7. How to use AI to reference button guidelines and directly generate button designs <a class="header-anchor" href="#_7-how-to-use-ai-to-reference-button-guidelines-and-directly-generate-button-designs" aria-label="Permalink to “7. How to use AI to reference button guidelines and directly generate button designs”">​</a></h2><p>If you just want to start with buttons, you can also directly paste button guideline excerpts.</p><p>For example, Atlassian&#39;s definition of a button is very brief:</p><blockquote><p><a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">&quot;A button triggers an event or action.&quot;</a></p></blockquote><p>You can ask AI like this:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Reference this sentence from Atlassian:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;A button triggers an event or action.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Help me design a set of button styles for an admin panel.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">I need a primary button, a secondary button, and a delete button. Also tell me where each should be used.</span></span></code></pre></div><p>This kind of prompt is especially suitable for beginners -- it&#39;s basically &quot;paste original text + state your requirements.&quot;</p><h2 id="_8-summary" tabindex="-1">8. Summary <a class="header-anchor" href="#_8-summary" aria-label="Permalink to “8. Summary”">​</a></h2><p>When designing pages and buttons by referencing UI design guidelines, the most important thing is not &quot;making it look like someone else&#39;s work&quot; but learning the following:</p><ol><li>Use hierarchy to organize pages rather than stacking content</li><li>Use button ranking to express action priority rather than making all buttons equally eye-catching</li><li>Use the definitions, boundaries, and judgment criteria from design guidelines to guide your design</li><li>When having AI reference established guidelines, reference the &quot;principles and structure&quot; rather than just the skin</li></ol><p>When you use guidelines this way, you&#39;re not just referencing a style -- you&#39;re adopting a mature way of thinking about design.</p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><p>The following links are all from official design systems or official documentation:</p><ul><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">Overview</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">Menus</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">Alerts</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/buttons" target="_blank" rel="noreferrer">Buttons</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/HowMenusWork.html" target="_blank" rel="noreferrer">How Menus Work</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">Managing Pop-Up Buttons and Pull-Down Lists</a></li><li>Material Design: <a href="https://m3.material.io/components/buttons/overview" target="_blank" rel="noreferrer">Buttons overview</a></li><li>Material Design: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">Menus</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/get-started/design" target="_blank" rel="noreferrer">Start designing</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">Menu usage</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">Button usage</a></li><li>Atlassian Design System: <a href="https://atlassian.design/foundations/" target="_blank" rel="noreferrer">Foundations</a></li><li>Atlassian Design System: <a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">Button</a></li></ul>`,146)])])}const g=t(s,[["render",o]]);export{p as __pageData,g as default};
